mapper.select:
select
count(distinct sdn.id)
FROM so_delivery_notice sdn
INNER JOIN so_delivery_notice_detail sdnd ON sdn.id = sdnd.main_id AND sdn.is_deleted = FALSE
WHERE sdnd.is_deleted = FALSE

    and sdn.approve_status in

        #{item}



    and sdn.delivery_status = #{params.deliveryStatus}


    and sdn.is_allow_outstock = #{params.isAllowOutstock}



    ${params.permissionSql}

SELECT sdn.id, sdn.source_id AS sourceId, sdnd.source_detail_id AS sourceDetailId, sdn.code, sdn.source_code AS sourceCode, sdn.customer_id AS customerId, sdn.customer_name AS customerName, sdn.approve_status AS approveStatus, sdn.invalid_status AS invalidStatus, sdn.delivery_status AS deliveryStatus, sdn.warehouse_org_id AS warehouseOrgId, sdn.warehouse_org_name AS warehouseOrgName, sdn.is_allow_outstock as isAllowOutstock, sdnd.sku_id AS skuId, sdnd.sku_no AS skuNo, sdnd.delivery_qty AS deliveryQty, sdnd.customer_po AS customerPO, sdnd.to_country AS toCountry, sdn.declare_status AS declareStatus, sdn.seller_name AS sellerName, sdn.require_date AS requireDate, sdn.plan_delivery_date AS planDeliveryDate, sdn.actual_delivery_date AS actualDeliveryDate, sdn.approve_user_name AS approveUserName, sdn.create_user_name AS createUserName, sdn.create_time AS createTime, sdn.transfer_warehouse_ids FROM so_delivery_notice sdn INNER JOIN so_delivery_notice_detail sdnd ON sdn.id = sdnd.main_id AND sdn.is_deleted = FALSE WHERE ${params.sqlMap.default} and sdnd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sdn.create_time desc

SELECT sdn.id AS sourceId, sdn.source_id AS soId, sdn.code AS sourceCode, sdn.warehouse_org_id, sdn.warehouse_org_name, sdn.plan_delivery_date, sdn.carrier_id, sdn.track_no, sdn.warehouse_id, sdn.warehouse_name, sdn.type AS orderType, sdnd.id AS sourceDetailId, sdnd.source_detail_id as soDetailId, sdnd.sku_id, sdnd.is_close, sdnd.sku_no, COALESCE(sdnd.picking_qty, 0) as qty, sdn.seller_id, sdn.seller_name, sdnd.remark FROM so_delivery_notice sdn INNER JOIN so_delivery_notice_detail sdnd ON sdn.id=sdnd.main_id AND sdnd.is_deleted=FALSE WHERE sdn.is_deleted=FALSE
and sdn.id in
#{id}

SELECT sdn.id, sdn.source_id, sdnd.source_detail_id, sdn.code, sdn.source_code, sdn.customer_id, sdn.customer_name, sdn.approve_status, sdn.invalid_status, sdn.delivery_status, sdnd.sku_id, sdnd.sku_no, sdnd.delivery_qty, sdn.seller_name, sdn.require_date, sdn.plan_delivery_date, sdn.actual_delivery_date, sdn.approve_user_name, sdn.create_user_name, sdn.warehouse_org_id, sdn.warehouse_org_name, sdn.create_time FROM so_delivery_notice sdn INNER JOIN so_delivery_notice_detail sdnd ON sdn.id = sdnd.main_id AND sdn.is_deleted = FALSE WHERE sdnd.is_deleted = FALSE
AND sdn.source_id = #{sourceId}
ORDER BY sdn.create_time DESC

select sdnd.id AS detailId, sdnd.sku_no AS skuNo, sdnd.platform_sku_no AS platformSkuNo, sdnd.sku_id AS skuId, sdnd.delivery_qty AS planQty, sdnd.picking_qty AS pickedQuantity, sdnd.delivery_qty - sdnd.picking_qty AS unpickedQuantity from so_delivery_notice sdn inner join so_delivery_notice_detail sdnd ON sdn.id = sdnd.main_id AND sdnd.is_deleted = FALSE where sdn.is_deleted = false and sdn.id = #{id} and sdnd.delivery_qty > sdnd.picking_qty
and sdnd.sku_id not in
#{sku}

select sdn.id as sourceId, sdn.code as sourceCode, 'soDeliveryNotice' as sourceType, sdnd.id as sourceDetailId, sdn.source_id as businessId, sdn.source_code as businessCode, sdnd.sku_id as skuId, sdnd.sku_no as skuNo, wc.delivery_qty as qty, wc.box_no, ci.country_id, sdn.warehouse_id as fromWarehouseId, sdn.warehouse_name as fromWarehouseName, sdn.warehouse_org_id as fromWarehouseOrgId, sdn.warehouse_org_name as fromWarehouseOrgName, sdn.transfer_warehouse_ids as transferWarehouseIds, sdn.sales_org_id AS salesOrgId, sdn.sales_org_name AS salesOrgName from so_delivery_notice sdn left join so_delivery_notice_detail sdnd on sdn.id = sdnd.main_id and sdnd.is_deleted = false left join packing_task_detail ptd on sdnd.id = ptd.source_detail_id and ptd.is_deleted = false left join packing_task pt on ptd.main_id = pt.id and pt.is_deleted = false and pt.packing_status = 'packed' left join wms_carton wc on pt.id = wc.packing_task_id and wc.is_deleted = false left join customer_info ci on sdn.customer_id = ci.id and ci.is_deleted = false where sdn.is_deleted = false and sdn.declare_status = 'wait' and wc.box_no is not null and sdn.id in
#{id}
and sdnd.id in
#{id}
